const { chromium } = require('playwright');
(async () => {
  const url = process.argv[2];
  const out = process.argv[3];
  const w = parseInt(process.argv[4] || '1920');
  const h = parseInt(process.argv[5] || '1080');
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  await page.goto(url, { waitUntil: 'networkidle', timeout: 60000 }).catch(e => errors.push('GOTO ' + e.message));
  await page.waitForTimeout(2500);
  await page.screenshot({ path: out, fullPage: false });
  const info = await page.evaluate(() => ({ title: document.title, bodyLen: document.body.innerText.length }));
  console.log(JSON.stringify({ out, w, h, info, errors: errors.slice(0,10) }, null, 2));
  await browser.close();
})();

