  const isLocalTarget = /^https?:\/\/(localhost|127\.0\.0\.1|\[::1\]|192\.168\.)/i.test(target || "");
  const escapedProxyContext = String(proxyContext || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

  return {
    target,
    changeOrigin: true,
    ...(shouldStripApiPrefix && isLocalTarget
      ? {
          rewrite: (path) => path.replace(new RegExp(`^${escapedProxyContext}`), "") || "/",
        }
      : {}),
    bypass(req, res, options) {
      const rewrittenUrl = options.rewrite ? options.rewrite(req.url) : req.url;
      res.setHeader("frontend-proxy", `${options.target}${rewrittenUrl}`);
    },
  };
}

/** 静态资源（/zhi2、/zhi2-dev 等）代理目标：挂在网关根路径，不能拼在 /v3.0 下 */
