  const apiTarget = (env.VITE_APP_PROXY_ADDRESS || "").trim().replace(/\/+$/, "");
  return apiTarget.replace(/\/v3\.0$/i, "") || apiTarget;
}

function createStaticFileProxyConfig(target) {
