const fs = require('fs');
const s = fs.readFileSync('.workbuddy/icons-raw.js', 'utf8');
// Parse: name=M(`icon-name`, [[`tag`,{attrs}],[...]]),
// We'll scan for pattern  name=M(`xxx`,[ ... ]) up to the matching close before next ,name=M( or end
const BV = String.fromCharCode(96);
// Find each icon start: \w+=M(`name`,[
const startRe = new RegExp('(\\w+)=M\\(\\' + BV + '([\\w-]+)\\' + BV + ',\\[', 'g');
let m, starts = [];
while ((m = startRe.exec(s))) starts.push({ name: m[1], icon: m[2], bodyStart: m.index + m[0].length, idx: m.index });
// For each, find matching bracket: body ends with `]]),` — we look for the ']]],' pattern? Each node is [tag,{...}]
// Structure: name=M(`x`,[[`tag`,{...}],[`tag`,{...}]]),
// The array closes with ']])'. Find the ends: scan counting [ ] from bodyStart to close.
function findClose(str, from) {
  // from points just after the outer '[' (bodyStart). Count depth starting at 1 (outer array)
  let depth = 1, i = from;
  while (i < str.length) {
    const c = str[i];
    if (c === '[') depth++;
    else if (c === ']') { depth--; if (depth === 0) return i; }
    else if (c === BV) { // skip template string
      i++;
      while (i < str.length && str[i] !== BV) i++;
    } else if (c === '{') { // skip object, need count braces and strings
      // naive: scan to matching } respecting template strings
      let d = 1; i++;
      while (i < str.length && d > 0) {
        const cc = str[i];
        if (cc === BV) { i++; while (i < str.length && str[i] !== BV) i++; }
        else if (cc === '{') d++;
        else if (cc === '}') d--;
        i++;
      }
      continue;
    }
    i++;
  }
  return -1;
}
const out = {};
for (const st of starts) {
  // bodyStart points after '['; find close of outer array
  const close = findClose(s, st.bodyStart);
  // body is s.slice(bodyStart, close) : that's the array *contents* (nodes), excluding final ']'
  const nodesSrc = s.slice(st.bodyStart, close);
  // Parse nodes: each node = [`tag`,{attrs}]
  // We'll use a relaxed eval by converting backticks to quotes
  let nodes;
  try {
    const clean = nodesSrc.replace(new RegExp(BV, 'g'), '"');
    nodes = JSON.parse('[' + clean + ']');
  } catch (e) {
    out[st.icon] = { __error: e.message, src: nodesSrc.slice(0, 80) };
    continue;
  }
  out[st.icon] = nodes.map(n => ({ tag: n[0], attrs: n[1] }));
}
fs.writeFileSync('.workbuddy/icons-map.json', JSON.stringify(out, null, 2));
console.log('icons parsed:', Object.keys(out).length, Object.keys(out).join(','));
const errs = Object.entries(out).filter(([k,v])=>v.__error);
console.log('errors:', errs.length, errs.map(e=>e[0]+':'+e[1].__error).join(' | '));

