    s = s.trim();
    if (!s) return s;
    if (s.startsWith(SCOPE)) return s;
    // handle html/body/:root -> scope; and * 
    if (s === ':root' || s === 'html' || s === 'body') return SCOPE;
    if (s === 'html, body' || s === 'html,body') return SCOPE;
    if (s === '*') return SCOPE + ' *';
    if (s.startsWith('::') ) return SCOPE + s; // pseudo like ::backdrop
    if (s.startsWith('*')) return SCOPE + ' ' + s;
    return SCOPE + ' ' + s;
  }).join(', ');
}

// Parse top-level rules
function processRules(text) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    // skip whitespace
    while (i < text.length && /\s/.test(text[i])) { out += text[i]; i++; }
    if (i >= text.length) break;
    if (text[i] === '@') {
      // parse at-rule prelude up to { or ;
      let j = i;
      while (j < text.length && text[j] !== '{' && text[j] !== ';') j++;
      const prelude = text.slice(i, j).trim();
      if (text[j] === ';') { out += prelude + ';'; i = j + 1; continue; }
      // find matching brace
      let depth = 0, k = j;
      let start = j;
      while (k < text.length) {
        if (text[k] === '{') depth++;
        else if (text[k] === '}') { depth--; if (depth === 0) { k++; break; } }
        k++;
      }
      const body = text.slice(start + 1, k - 1);
      const atName = prelude.split(/\s+/)[0].toLowerCase();
      if (atName === '@layer' || atName === '@media' || atName === '@supports' || atName === '@container') {
        out += prelude + '{' + processRules(body) + '}';
      } else {
        // @keyframes, @font-face, @property, @page : pass through unchanged
        out += prelude + '{' + body + '}';
      }
      i = k;
      continue;
    }
    // regular rule: selector up to {
    let j = i;
    while (j < text.length && text[j] !== '{') j++;
    if (j >= text.length) break;
    const sel = text.slice(i, j).trim();
    let depth = 0, k = j;
    while (k < text.length) {
      if (text[k] === '{') depth++;
      else if (text[k] === '}') { depth--; if (depth === 0) { k++; break; } }
      k++;
    }
    const body = text.slice(j + 1, k - 1);
    if (sel.startsWith('@')) {
      out += sel + '{' + body + '}';
    } else {
      out += prefixSelector(sel) + '{' + body + '}';
    }
    i = k;
  }
  return out;
}

