const fs = require('fs');
const s = fs.readFileSync('.workbuddy/dashboard-src.html', 'utf8');
const BV = String.fromCharCode(96);

// Extract an assignment value starting at `name=` position, returning the raw value text.
function extractVar(varname, searchFrom = 0) {
  const re = new RegExp('(^|[,;{])\\s*' + varname.replace(/\$/g, '\\$') + '\\s*=');
  re.lastIndex = searchFrom;
  // manual search
  let idx = -1;
  const g = new RegExp('(^|[,;{])\\s*' + varname.replace(/\$/g, '\\$') + '\\s*=', 'g');
  let mm;
  while ((mm = g.exec(s))) { if (mm.index >= searchFrom) { idx = mm.index + mm[0].length; break; } }
  if (idx < 0) return null;
  // value begins after '=' possibly whitespace
  // skip whitespace
  let i = idx;
  while (/\s/.test(s[i])) i++;
  const startCh = s[i];
  if (startCh === '[' || startCh === '{') {
    const closeCh = startCh === '[' ? ']' : '}';
    let depth = 0, j = i;
    while (j < s.length) {
      const c = s[j];
      if (c === BV) { j++; while (j < s.length && s[j] !== BV) j++; }
      else if (c === startCh) depth++;
      else if (c === closeCh) { depth--; if (depth === 0) { j++; break; } }
      j++;
    }
    return s.substring(i, j);
  }
  // primitive: read until top-level , or ; 
  let j = i;
  while (j < s.length && s[j] !== ',' && s[j] !== ';') { if (s[j] === BV) { j++; while (j < s.length && s[j] !== BV) j++; } j++; }
  return s.substring(i, j);
}

