    // quote bare keys
    json = json.replace(/([{,])\s*([A-Za-z_$][\w$]*)\s*:/g, '$1"$2":');
    try {
      out[v] = JSON.parse(json);
      console.log(v, 'OK', Array.isArray(out[v]) ? '[' + out[v].length + ']' : 'obj');
    } catch (e) {
      console.log(v, 'PARSE_ERR', e.message, JSON.stringify(val.slice(0, 60)));
    }
  } else console.log(v, 'NOTFOUND');
}
