const fs = require('fs');
const s = fs.readFileSync('.workbuddy/dashboard-src.html', 'utf8');
const B = String.fromCharCode(96);
function valAtEq(eqIdx) {
  let i = eqIdx;
  while (s[i] !== '[' && s[i] !== '{') i++;
  const st = s[i], cl = st === '[' ? ']' : '}';
  let d = 0, j = i;
  while (j < s.length) {
    const c = s[j];
    if (c === B) { j++; while (s[j] !== B) j++; }
    else if (c === st) d++;
    else if (c === cl) { d--; if (d === 0) { j++; break; } }
    j++;
  }
  return s.substring(i, j);
}
function toJson(v) {
  let j = v.replace(new RegExp(B, 'g'), '"');
  j = j.replace(/([{,])\s*([^\s,:{}"]+)\s*:/g, (m0, p1, p2) => p1 + '"' + p2 + '":');
  j = j.replace(/^\s*([^\s,:{}"]+)\s*:/, (m0, p2) => '"' + p2 + '":');
  j = j.replace(/([:\[,])-\.(\d)/g, '$1-0.$2');
  j = j.replace(/([:\[,])\.(\d)/g, '$10.$2');
  j = j.replace(/(\d)\.(?=[,\]}])/g, '$1.0');
  return JSON.parse(j);
}
const positions = { S: 223518, x: 221839, C: 224008, w: 224411 };
const d = JSON.parse(fs.readFileSync('.workbuddy/data-map.json', 'utf8'));
for (const [k, pos] of Object.entries(positions)) {
  try { d[k] = toJson(valAtEq(pos)); console.log(k, 'OK', Array.isArray(d[k]) ? d[k].length : 'obj'); }
  catch (e) { console.log(k, 'ERR', e.message, JSON.stringify(s.substr(pos, 60))); }
}
fs.writeFileSync('.workbuddy/data-map.json', JSON.stringify(d, null, 2));
console.log('keys', Object.keys(d));

