[{"type":"text","text":"=== 门户.conf ===
###ENC=UTF8
# 门户(zhi2-web-admin) 本地部署 —— nginx 站点 (root 指向本项目 dist)
# 代理对齐 env VITE_APP_PROXY_ADDRESS（v2 网关）

# ---- 弱网优化：文本资源压缩 ----
# dist 里 js+css 共 21.2MB，gzip 后 6.8MB（约 32%）。
# 原来没有开 gzip，弱网/移动网络下首屏同步资源 1.17MB 原样传输，是白屏等待的主因之一。
# 这里只压缩文本类资源（图片/字体已是二进制，压缩反而浪费 CPU）。
# text/html 在没有显式 gzip_types 时总是被压缩，这里显式列出便于阅读。
gzip on;
gzip_comp_level 5;
gzip_min_length 1024;
gzip_vary on;
gzip_proxied any;
gzip_http_version 1.1;
gzip_types
    text/plain
    text/css
    text/xml
    text/javascript
    application/javascript
    application/json
    application/manifest+json
    application/xml
    application/rss+xml
    application/atom+xml
    image/svg+xml
    font/ttf
    font/otf;

server {
    listen 8092;
    server_name localhost;
    root D:/repository/门户/dist;
    index index.html;
    charset utf-8;
    client_max_body_size 100m;

    # 代理公共配置（以下 all proxy_pass location 继承）
    proxy_http_version 1.1;
    proxy_set_header Connection "";
    proxy_set_header Host unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_connect_timeout 60s;
    proxy_send_timeout 120s;
    proxy_read_timeout 120s;

    # 静态资源缓存
    # 文件名带内容 hash，可以长缓存；配合下方的 /index.html no-cache，
    # 发版后用户刷新即拿到新 HTML，chunk 命中本地缓存不重复下载。
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
        # 注意：add_header 会让本 location 不再继承上层 Cache-Control，
        # 所以这里只写一条完整的 Cache-Control（别再配 expires，避免出现两个 max-age）。
        add_header Cache-Control "public, max-age=2592000, immutable" always;
        access_log off;
        try_files $uri =404;
    }
    location = /index.html {
        expires -1;
        add_header Cache-Control "no-cache, no-store, must-revalidate";
        add_header Pragma "no-cache";
    }
    # 站点版本号（前端发版检测用）：不缓存，弱网下也要拿到最新值
    location = /version.json {
        add_header Cache-Control "no-cache, no-store, must-revalidate";
    }

    # 业务 API（门户网关：保留 /api/v2.0、/api/v3.0 前缀）
    location /api/v2.0/ {
        proxy_pass http://unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
    }
    location /api/v3.0/ {
        proxy_pass http://unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
    }
    # 附件/静态代理（对齐 vite /zhi2* proxy）
    location ^~ /zhi2/ {
        proxy_pass http://unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
    }
    location ^~ /zhi2-dev/ {
        proxy_pass http://unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
    }
    location ^~ /zhi2-test/ {
        proxy_pass http://unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}

