const fs = require('fs');
const path = 'zhi2-web-admin/src/views/property/marketMonitor/components';
const files = fs.readdirSync(path).filter(f => f.endsWith('.vue'));
for (const f of files) {
  const src = fs.readFileSync(path + '/' + f, 'utf8');
  const tplStart = src.indexOf('<template>');
  const tplEnd = src.lastIndexOf('</template>');
  if (tplStart < 0) continue;
  const tpl = src.substring(tplStart + 10, tplEnd);
  // collect imported bindings from script
  const script = src.substring(tplEnd);
  const imports = [];
  const re = /import\s+(?:\{([^}]+)\}|(\w+))\s+from/g;
  let m;
  while ((m = re.exec(script))) {
    if (m[1]) m[1].split(',').forEach(s => { const name = s.split(' as ').pop().trim(); if (name) imports.push(name); });
    else if (m[2]) imports.push(m[2]);
  }
  // strip component tag names (imports used as <component>) - they're fine in components:{}
  // Check each import that is NOT a component (heuristic: components appear as <kebab> or <Pascal>)
  const suspicious = [];
  for (const name of imports) {
    // if used in template WITHOUT this. context: look for \bname\b in tpl but not preceded by this. or - or as tag <
    const re2 = new RegExp('(^|[^\\w.\'"-])' + name + '\\b', 'g');
    let mm, used = false;
    while ((mm = re2.exec(tpl))) {
      // exclude when it's a component tag <Name or </Name
      const before = tpl.substring(Math.max(0, mm.index - 1), mm.index + 1);
      if (before === '<' ) continue;
      used = true; break;
    }
    if (used) suspicious.push(name);
  }
  if (suspicious.length) console.log(f, '=> imports used in template:', suspicious.join(', '));
}

