  const info = await page.evaluate(() => {
    // find the KPI grid: element with children 6 cards, has class containing grid
    const grids = [...document.querySelectorAll('.mm-dashboard [class*="grid-cols"]')];
    const kpi = grids.find(g => g.className.includes('xl:grid-cols-6'));
    if (!kpi) return { found: false, gridCount: grids.length, sample: grids.slice(0,3).map(g=>g.className) };
    const cs = getComputedStyle(kpi);
    return {
      found: true,
      className: kpi.className,
      display: cs.display,
      gridTemplateColumns: cs.gridTemplateColumns,
      width: kpi.getBoundingClientRect().width,
      parentDisplay: getComputedStyle(kpi.parentElement).display,
    };
  });
  // Also check if the css file loaded and whether a media rule matches
  const mediaInfo = await page.evaluate(() => {
    return {
      matchSm: window.matchMedia('(width>=40rem)').matches,
      matchSmAlt: window.matchMedia('(min-width:640px)').matches,
    };
  });
  console.log(JSON.stringify({ info, mediaInfo }, null, 2));
  await browser.close();
})();

