    const kpi = [...document.querySelectorAll('.mm-dashboard [class*="xl:grid-cols-6"]')][0];
    const out = { matchesPrefixed: kpi.matches('.mm-dashboard .sm\\:grid-cols-2'), sheets: [] };
    for (const sheet of Array.from(document.styleSheets)) {
      let count = 0, hasSmGrid = false, href = sheet.href || '(inline)';
      try {
        const walk = (list) => { for (const rule of Array.from(list)) {
          if (rule.conditionText !== undefined || rule.constructor.name === 'CSSMediaRule') { walk(rule.cssRules); continue; }
          if (rule.selectorText) { count++; if (rule.selectorText.includes('sm\\:grid-cols-2')) hasSmGrid = true; }
        }};
        walk(sheet.cssRules);
      } catch (e) {}
      out.sheets.push({ href: href.split('/').pop(), ruleCount: count, hasSmGrid });
    }
    return out;
  });
  console.log(JSON.stringify(r, null, 2));
  await browser.close();
})();

