/**
 * 房地产市场运行监测决策大屏 - 视觉/结构 E2E
 *
 * 目标：
 *  - 验证 /market-monitor 页面渲染关键板块结构（6 KPI 卡片、商品/存量成交面板、
 *    中介机构、成交面积段、累计可售房屋(3 tab)、购房人总览、付款方式左右布局）。
 *  - 多分辨率截图对比：1920x1080 / 1920x1040（本机工作区） / 1366x768，
 *    确认无遮挡（内容整体可见、无纵向溢出裁切）。
 *  - 交互：切换 累计可售房屋 的 套数走势/面积走势/未售情况 tab。
 *
 * 运行：PLAYWRIGHT_BASE_URL=http://127.0.0.1:8092 npx playwright test tests/e2e/market-monitor-visual.spec.ts
 * 基线截图位于 tests/e2e/screenshots/market-monitor/*.png
 */
import { test, expect } from '@playwright/test'
import path from 'path'
import fs from 'fs'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const shotDir = path.join(__dirname, 'screenshots', 'market-monitor')
const REGION = '/market-monitor'

async function open(page: import('@playwright/test').Page, w: number, h: number) {
  await page.setViewportSize({ width: w, height: h })
  await page.goto(`/index.html#${REGION}`, { waitUntil: 'networkidle' })
  await page.waitForSelector('.mm-dashboard', { timeout: 20000 })
  await page.waitForTimeout(1200) // echarts 动画
}

test.beforeAll(() => {
  fs.mkdirSync(shotDir, { recursive: true })
})

test('结构：关键板块与 6 个 KPI 卡片存在', async ({ page }) => {
  await open(page, 1920, 1080)
  // 标题
  await expect(page.locator('.mm-dashboard')).toContainText('苏州市房地产市场数据分析平台')
  // 6 个 KPI 卡片头部标题
  for (const t of ['商品房批准量', '商品房成交量', '存量房挂牌量', '存量房成交量', '测绘成果备案数', '租赁合同备案']) {
    await expect(page.locator('.mm-dashboard').getByText(t, { exact: true }).first()).toBeVisible()
  }
  // 面板存在
  for (const t of ['商品住房', '存量住房', '中介机构', '成交面积段', '累计可售房屋', '购房人总览', '付款方式结构']) {
    await expect(page.locator('.mm-dashboard').getByText(t, { exact: false }).first()).toBeVisible()
  }
  // 累计可售三个 tab
  for (const t of ['套数走势 (万套)', '面积走势 (万㎡)', '未售情况']) {
    await expect(page.locator('.mm-dashboard button', { hasText: t }).first()).toBeVisible()
  }
})

test('无遮挡：1920x1040（本机工作区）内容完整可见不溢出', async ({ page }) => {
  await open(page, 1920, 1040)
  const info = await page.evaluate(() => {
    const root = document.querySelector('.mm-dashboard') as HTMLElement
    const docH = document.documentElement.scrollHeight
    const winH = window.innerHeight
    // 找最底部的可见元素（付款方式/累计可售 面板底边）
    const panels = Array.from(document.querySelectorAll('.mm-dashboard main > div')) as HTMLElement[]
    const maxBottom = Math.max(...panels.map((p) => p.getBoundingClientRect().bottom))
    return { docH, winH, maxBottom: Math.round(maxBottom), rootH: Math.round(root.getBoundingClientRect().height) }
  })
  // 整页应恰好适配视口高度，不发生纵向溢出裁切
  expect(info.docH, 'document scrollHeight 不应超过视口（无纵向滚动/遮挡）').toBeLessThanOrEqual(info.winH + 2)
  // 底部板块底边不超过视口
  expect(info.maxBottom, '最底部板块底边应在视口内').toBeLessThanOrEqual(info.winH + 2)
  await page.screenshot({ path: path.join(shotDir, 'viewport-1920x1040.png') })
})

