  // 付款方式结构左右布局：图表 + 三项图例
  const payPanel = page.locator('.mm-dashboard', { hasText: '付款方式结构' })
  for (const t of ['商业贷款', '一次性付款', '分期付款']) {
    await expect(page.locator('.mm-dashboard').getByText(t, { exact: false }).first()).toBeVisible()
