import { defineConfig, devices } from '@playwright/test'

export default defineConfig({
  testDir: './zhi2-web-admin/tests/e2e',
  testMatch: /market-monitor-visual\.spec\.ts/,
  timeout: 60_000,
  expect: { timeout: 10_000 },
  use: {
    baseURL: process.env.PLAYWRIGHT_BASE_URL || 'http://127.0.0.1:8092',
    trace: 'off'
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'], viewport: { width: 1920, height: 1080 } }
    }
  ]
})

// Standalone E2E runner using root playwright 1.51 (working browsers).
// Mirrors tests/e2e/market-monitor-visual.spec.ts assertions and produces screenshots.
const { chromium } = require('playwright');
const { PNG } = require('pngjs');
const pmMod = require('pixelmatch');
const pixelmatch = pmMod.default || pmMod;
const fs = require('fs');
const path = require('path');

const BASE = process.env.PLAYWRIGHT_BASE_URL || 'http://127.0.0.1:8092';
const URL = BASE + '/index.html#/market-monitor';
const SHOT = path.resolve(__dirname, '../zhi2-web-admin/tests/e2e/screenshots/market-monitor');
fs.mkdirSync(SHOT, { recursive: true });

const results = [];
function check(name, cond, detail) {
  results.push({ name, pass: !!cond, detail });
  console.log(`${cond ? 'PASS' : 'FAIL'} - ${name}${detail ? ' :: ' + detail : ''}`);
}

async function open(page, w, h) {
  await page.setViewportSize({ width: w, height: h });
  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.waitForSelector('.mm-dashboard', { timeout: 20000 });
  await page.waitForTimeout(1200);
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('C:' + m.text()); });

  // 1. Structure test at 1920x1080
  await open(page, 1920, 1080);
  const bodyText = await page.locator('.mm-dashboard').innerText();
  check('标题存在', bodyText.includes('苏州市房地产市场数据分析平台'));
  for (const t of ['商品房批准量', '商品房成交量', '存量房挂牌量', '存量房成交量', '测绘成果备案数', '租赁合同备案']) {
    check('KPI卡片: ' + t, bodyText.includes(t));
  }
  for (const t of ['商品住房', '存量住房', '中介机构', '成交面积段', '累计可售房屋', '购房人总览', '付款方式结构']) {
    check('面板: ' + t, bodyText.includes(t));
  }
  for (const t of ['套数走势 (万套)', '面积走势 (万㎡)', '未售情况']) {
    check('tab按钮: ' + t, (await page.locator('.mm-dashboard button', { hasText: t }).count()) > 0);
  }
  await page.screenshot({ path: path.join(SHOT, 'full-1920x1080.png') });

  // 2. No-occlusion test at 1920x1040
  await open(page, 1920, 1040);
  const geo = await page.evaluate(() => {
    const panels = Array.from(document.querySelectorAll('.mm-dashboard main > div'));
    const maxBottom = Math.max(...panels.map(p => p.getBoundingClientRect().bottom));
    return { docH: document.documentElement.scrollHeight, winH: window.innerHeight, maxBottom: Math.round(maxBottom) };
  });
  check('无纵向溢出(docH<=winH)', geo.docH <= geo.winH + 2, JSON.stringify(geo));
  check('底部板块在视口内', geo.maxBottom <= geo.winH + 2, JSON.stringify(geo));
  await page.screenshot({ path: path.join(SHOT, 'full-1920x1040.png') });

  // 3. Multi-resolution screenshots
  for (const [w, h] of [[1920, 1080], [1920, 1040], [1366, 768]]) {
    await open(page, w, h);
    await page.screenshot({ path: path.join(SHOT, `full-${w}x${h}.png`) });
    check(`截图 ${w}x${h}`, true);
  }

  // 4. Interaction: tabs + payment layout
  await open(page, 1920, 1040);
  await page.locator('.mm-dashboard button', { hasText: '未售情况' }).first().click();
  await page.waitForTimeout(500);
  const unsoldText = await page.locator('.mm-dashboard').innerText();
  check('未售tab显示一年未售', unsoldText.includes('一年未售'));
  check('未售tab显示三年未售', unsoldText.includes('三年未售'));
  check('未售tab显示多年未售', unsoldText.includes('多年未售'));
  await page.screenshot({ path: path.join(SHOT, 'tab-unsold.png') });
  await page.locator('.mm-dashboard button', { hasText: '套数走势' }).first().click();
  await page.waitForTimeout(400);
  const payText = await page.locator('.mm-dashboard').innerText();
  for (const t of ['商业贷款', '一次性付款', '分期付款']) check('付款方式项: ' + t, payText.includes(t));

  check('无运行时错误', errors.length === 0, errors.slice(0, 3).join(' | '));

  await browser.close();

  // 5. Pixel diff vs original reference (if present)
  const refPath = path.resolve(__dirname, 'ref-1920.png');
  const minePath = path.join(SHOT, 'full-1920x1080.png');
  if (fs.existsSync(refPath)) {
    const a = PNG.sync.read(fs.readFileSync(refPath));
    const b = PNG.sync.read(fs.readFileSync(minePath));
    if (a.width === b.width && a.height === b.height) {
      const diff = new PNG({ width: a.width, height: a.height });
      const n = pixelmatch(a.data, b.data, diff.data, a.width, a.height, { threshold: 0.1, includeAA: false });
      const ratio = (n / (a.width * a.height) * 100).toFixed(2);
      fs.writeFileSync(path.join(SHOT, 'diff-vs-original.png'), PNG.sync.write(diff));
      console.log(`\n像素对比(原版 vs 移植版, 1920x1080): 差异 ${n} px = ${ratio}% (相同 ${(100 - ratio).toFixed(2)}%)`);
    }
  }

  const failed = results.filter(r => !r.pass);
  console.log(`\n总计 ${results.length} 项断言, 通过 ${results.length - failed.length}, 失败 ${failed.length}`);
  process.exit(failed.length ? 1 : 0);
})().catch(e => { console.error(e); process.exit(2); });

